<?php
ini_set('session.cookie_samesite','Lax'); ini_set('session.cookie_secure','0'); session_start();
if(!isset($_SESSION['user'])){ header('Location: login.php'); exit; }
$isAdmin=$_SESSION['role']=='admin'; $file='data.json'; if(!file_exists($file)) file_put_contents($file,'[]');
$data=json_decode(file_get_contents($file),true);
if($_SERVER['REQUEST_METHOD']=='POST' && isset($_POST['subject'])){ $data[]= ['id'=>count($data)+1,'user'=>$_SESSION['user'],'subject'=>$_POST['subject'],'category'=>$_POST['category'],'desc'=>$_POST['desc'],'status'=>'Pending','date'=>date('d-m-Y')]; file_put_contents($file,json_encode($data)); header('Location: my_complaints.php'); exit; }
?>
<!DOCTYPE html><html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Complaints</title><style>*{box-sizing:border-box;margin:0;padding:0}body{font-family:Arial;background:#f8f7ff;display:flex;min-height:100vh}.side{width:240px;background:#fff;padding:22px}.side a{display:block;padding:11px;border-radius:10px;text-decoration:none;color:#6b7280;font-size:13px;margin:4px 0}.side a.active{background:#7c5cff;color:#fff}.main{flex:1;padding:28px}.card{background:#fff;padding:18px;border-radius:14px;box-shadow:0 4px 20px rgba(0,0,0,.04);margin-bottom:12px}</style></head><body><div class="side"><h3>✨ ResolveDesk</h3><a href="dashboard.php">Dashboard</a><a class="active" href="my_complaints.php">Complaints</a><a href="logout.php">Logout</a></div><div class="main"><h2>Complaints</h2><?php foreach(array_reverse($data) as $c){ if(!$isAdmin && $c['user']!=$_SESSION['user']) continue; echo "<div class=card><b>#{$c['id']} - {$c['subject']}</b> <small style='background:#fef9c3;padding:2px 8px;border-radius:10px'>{$c['status']}</small><br><small style=color:#999>{$c['category']} | {$c['date']}</small><p style='margin-top:6px;font-size:13px'>{$c['desc']}</p></div>"; } ?></div></body></html>
